/**
 * Manages text layout and an SDF font atlas for vectorized rendering based on Valve's '07 SIGGRAPH paper.
 * @see https://steamcdn-a.akamaihd.net/apps/valve/2007/SIGGRAPH2007_AlphaTestedMagnification.pdf
 */
export class FontManager {
    fontFamily: string;
    fontWeight: string;
    fontStyle: string;
    fontSize: number;
    width: number;
    height: number;
    glyphs: Map<any, any>;
    texture: any;
    version: number;
    getGlyphInfo(char: any): {
        char: any;
        data: Uint8ClampedArray<ArrayBuffer>;
        width: number;
        height: number;
        glyphWidth: number;
        glyphHeight: number;
        glyphTop: number;
        glyphLeft: number;
        glyphAdvance: number;
    };
    initCanvas(): void;
    canvas: HTMLCanvasElement | OffscreenCanvas;
    _alphabet: string;
    lineHeight: any;
    maxAscent: any;
    margin: number;
    glyphSize: number;
    ctx: OffscreenCanvasRenderingContext2D | RenderingContext;
    needsUpdate: boolean;
    update(chars: any): void;
    getLayoutInfo(text?: string): {
        glyphs: any[];
        width: number;
        height: number;
    };
}
